import { createContext, useContext, useEffect, useMemo, useState, type ButtonHTMLAttributes, type ChangeEvent, type FormEvent, type InputHTMLAttributes, type ReactNode, type TextareaHTMLAttributes, type SelectHTMLAttributes } from 'react';
import { Link, useLocation, useRoute } from 'wouter';
import { useQueryClient } from '@tanstack/react-query';
import {
  useGetBusinessProfile, getGetBusinessProfileQueryKey, useSaveBusinessProfile,
  useGetDashboardSummary, getGetDashboardSummaryQueryKey, useGenerateCampaignIdeas,
  useReviseCampaignIdea, useListCampaigns, getListCampaignsQueryKey, useCreateCampaign,
  useGetCampaign, getGetCampaignQueryKey, useUpdateCampaign, useDeleteCampaign,
} from '@workspace/api-client-react';
import type { BusinessProfile, BusinessProfileInput, Campaign, CampaignConcept, CampaignObjective, CampaignPlatform } from '@workspace/api-client-react';
import { useClerk } from '@clerk/react';
import {
  ArrowRight, BarChart3, BriefcaseBusiness, Check, ChevronDown, ChevronLeft, ChevronRight,
  CircleHelp, CloudOff, FileImage, FileVideo, Globe2, ImagePlus, LayoutDashboard, Link2,
  LoaderCircle, LogOut, Menu, MessageSquareText, Pencil, Plus, Save, Search, ShieldCheck,
  Sparkles, Trash2, Upload, X, type LucideIcon,
} from 'lucide-react';

const NAV = [
  { href: '/dashboard', label: 'Overview', icon: LayoutDashboard },
  { href: '/campaigns', label: 'Campaigns', icon: BarChart3 },
  { href: '/media', label: 'Media library', icon: FileImage },
  { href: '/business', label: 'Business profile', icon: BriefcaseBusiness },
  { href: '/connections', label: 'Connections', icon: Link2 },
];
const basePath = import.meta.env.BASE_URL.replace(/\/$/, '');
const OBJECTIVES: { value: CampaignObjective; label: string }[] = [
  { value: 'enquiries', label: 'Get more enquiries' }, { value: 'sales', label: 'Make more sales' },
  { value: 'website_visits', label: 'Bring people to my website' }, { value: 'awareness', label: 'Build awareness' },
];
const PLATFORMS: { value: CampaignPlatform; label: string; note: string }[] = [
  { value: 'google', label: 'Google', note: 'Search & display concepts' },
  { value: 'meta', label: 'Meta', note: 'Facebook & Instagram concepts' },
  { value: 'tiktok', label: 'TikTok', note: 'Short-form video concepts' },
];
const objectiveLabel = (value: string) => OBJECTIVES.find((o) => o.value === value)?.label ?? value.replaceAll('_', ' ');
const platformLabel = (value: string) => PLATFORMS.find((p) => p.value === value)?.label ?? value;
const currencyLabel = (currency?: string | null) => currency || 'NGN';
const statusLabel = (status: string) => status === 'ready_for_review' ? 'Ready for your review' : 'Draft';

function Button({ children, className = '', variant = 'primary', ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'plain' | 'danger' }) {
  const theme = variant === 'primary' ? 'bg-[#176ff0] text-white hover:bg-[#0d5fd7] shadow-[0_5px_14px_rgba(23,111,240,.16)]' :
    variant === 'danger' ? 'bg-red-50 text-red-700 hover:bg-red-100' :
    variant === 'plain' ? 'text-slate-600 hover:bg-slate-100' : 'border border-[#dce5f0] bg-white text-[#183252] hover:border-[#9cb9de] hover:bg-[#f8fbff]';
  return <button {...props} className={`focus-ring inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-bold transition duration-150 disabled:cursor-not-allowed disabled:opacity-55 ${theme} ${className}`} />;
}
function Field({ label, help, children, testid }: { label: string; help?: string; children: ReactNode; testid?: string }) {
  return <label className="grid gap-1.5 text-sm font-semibold text-[#203756]" data-testid={testid}><span>{label}</span>{children}{help && <span className="text-xs font-normal leading-relaxed text-slate-500">{help}</span>}</label>;
}
const inputClass = 'focus-ring w-full rounded-xl border border-[#d7e1ed] bg-white px-3.5 py-2.5 text-sm font-medium text-[#172c4b] placeholder:text-slate-400';
function TextInput(props: InputHTMLAttributes<HTMLInputElement>) { return <input {...props} className={`${inputClass} ${props.className ?? ''}`} />; }
function TextArea(props: TextareaHTMLAttributes<HTMLTextAreaElement>) { return <textarea {...props} className={`${inputClass} min-h-[96px] resize-y ${props.className ?? ''}`} />; }
function SelectInput({ children, ...props }: SelectHTMLAttributes<HTMLSelectElement>) { return <select {...props} className={`${inputClass} appearance-none`}>{children}</select>; }
function Tag({ children, tone = 'blue' }: { children: ReactNode; tone?: 'blue' | 'green' | 'gray' }) {
  const styles = tone === 'green' ? 'bg-emerald-50 text-emerald-800 ring-emerald-200' : tone === 'gray' ? 'bg-slate-100 text-slate-700 ring-slate-200' : 'bg-blue-50 text-blue-800 ring-blue-200';
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-xs font-bold ring-1 ring-inset ${styles}`}>{children}</span>;
}
function PageHead({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 text-[11px] font-extrabold uppercase tracking-[.18em] text-[#2674e9]">{eyebrow}</p>}<h1 className="font-display text-[28px] font-extrabold tracking-[-.04em] text-[#172c4b] sm:text-[34px]" data-testid="heading-page">{title}</h1>{detail && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600" data-testid="text-page-description">{detail}</p>}</div>{action}</div>;
}
function Skeleton({ className = '' }: { className?: string }) { return <div className={`animate-pulse rounded-xl bg-[#e4ebf3] ${className}`} />; }
function ErrorPanel({ retry, message = 'We could not load this just now.' }: { retry: () => void; message?: string }) {
  return <div className="rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm text-amber-950" data-testid="state-error"><p className="font-bold">{message}</p><p className="mt-1 text-amber-900/80">Your work is still here. Try again in a moment.</p><Button variant="secondary" className="mt-4" onClick={retry} data-testid="button-retry">Try again</Button></div>;
}
function EmptyPanel({ title, body, action }: { title: string; body: string; action?: ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-[#c5d4e5] bg-white px-6 py-12 text-center" data-testid="state-empty"><div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-[#edf4ff] text-[#2674e9]"><FileImage size={21}/></div><h3 className="font-display text-lg font-bold text-[#193252]">{title}</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-slate-600">{body}</p>{action && <div className="mt-5 flex justify-center">{action}</div>}</div>;
}

export function Landing() {
  return <div className="min-h-[100dvh] overflow-hidden bg-[#f7f9fc] text-[#142d50]">
    <header className="relative z-10 mx-auto flex max-w-7xl items-center justify-between px-5 py-5 lg:px-10">
      <Link href="/" className="flex items-center gap-3 font-display text-xl font-extrabold tracking-[-.04em]" data-testid="link-brand"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#176ff0] text-sm text-white">D</span>AdPilot</Link>
      <nav className="flex items-center gap-2"><Link href="/sign-in" className="rounded-xl px-4 py-2.5 text-sm font-bold text-[#304867] hover:bg-white" data-testid="link-sign-in">Sign in</Link><Link href="/sign-up" className="rounded-xl bg-[#176ff0] px-4 py-2.5 text-sm font-bold text-white shadow-lg shadow-blue-900/10 hover:bg-[#0d5fd7]" data-testid="link-get-started">Get started</Link></nav>
    </header>
    <main>
      <section className="relative mx-auto grid max-w-7xl items-center gap-12 px-5 pb-20 pt-14 lg:grid-cols-[1.07fr_.93fr] lg:px-10 lg:pb-28 lg:pt-20">
        <div className="absolute -right-28 top-5 h-[460px] w-[460px] rounded-full bg-[#dceaff] blur-[1px] md:right-0 md:top-10" aria-hidden="true"/>
        <div className="relative z-[1] page-enter"><p className="mb-5 inline-flex items-center gap-2 rounded-full border border-[#d7e5f7] bg-white px-3 py-1.5 text-xs font-bold text-[#2867bb]"><span className="h-1.5 w-1.5 rounded-full bg-[#2582ff]"/>For small businesses, without the ad jargon</p>
          <h1 className="font-display max-w-[700px] text-[43px] font-extrabold leading-[1.06] tracking-[-.06em] text-[#142d50] sm:text-[60px] lg:text-[68px]">Plan your first ad with a <span className="text-[#176ff0]">clear next step.</span></h1>
          <p className="mt-6 max-w-xl text-lg leading-8 text-[#50647f]">Tell Dummy about your business. Get three editable, clearly labeled starter concepts based on the details you provide.</p>
          <div className="mt-8 flex flex-wrap items-center gap-3"><Link href="/sign-up" className="inline-flex min-h-12 items-center gap-2 rounded-xl bg-[#176ff0] px-5 py-3 text-sm font-bold text-white shadow-[0_8px_20px_rgba(23,111,240,.2)] hover:bg-[#0d5fd7]" data-testid="link-create-workspace">Create your workspace <ArrowRight size={17}/></Link><a href="#how-it-works" className="rounded-xl px-4 py-3 text-sm font-bold text-[#344c6b] hover:bg-white" data-testid="link-how-it-works">See how it works</a></div>
          <div className="mt-8 flex items-center gap-2 text-xs font-semibold text-[#61748d]"><ShieldCheck size={15} className="text-[#2674e9]"/> Your selected files stay in this browser. No ad accounts are connected.</div>
        </div>
        <div className="relative z-[1] mx-auto w-full max-w-[540px] page-enter [animation-delay:90ms]">
          <div className="absolute -left-8 top-14 h-32 w-32 rounded-full border border-blue-200/70"/><div className="absolute -bottom-8 right-2 h-44 w-44 rounded-full bg-[#dceaff]"/>
          <div className="relative rounded-[28px] border border-[#d7e2ef] bg-white p-4 shadow-[0_28px_90px_rgba(25,57,98,.14)] sm:p-6">
            <div className="flex items-center justify-between border-b border-[#edf1f6] pb-4"><div><p className="text-[10px] font-extrabold uppercase tracking-[.16em] text-[#7790ae]">Your workspace</p><h2 className="mt-1 font-display text-lg font-extrabold">First campaign draft</h2></div><Tag>Draft</Tag></div>
            <div className="grid grid-cols-3 gap-2 py-5">{['01 Tell us','02 Shape ideas','03 Review'].map((s,i)=><div key={s} className="rounded-xl bg-[#f4f7fb] p-3"><div className={`mb-2 h-1 rounded-full ${i===0?'bg-[#176ff0]':'bg-[#dce6f2]'}`}/><p className="text-[10px] font-bold text-slate-500">{s}</p></div>)}</div>
            <div className="rounded-2xl bg-[#f5f8fc] p-4"><div className="flex items-start gap-3"><DummyVisual className="h-10 w-10 rounded-xl text-sm"/><div><div className="flex items-center gap-2"><span className="font-bold text-[#203958]">Dummy</span><Tag tone="gray">Rule-based</Tag></div><p className="mt-2 text-sm leading-6 text-[#536983]">Three ways to introduce your offer, ready for you to shape. Every line is editable.</p></div></div></div>
            <div className="mt-4 grid gap-2 sm:grid-cols-2"><div className="rounded-xl border border-[#e3eaf2] p-3"><p className="text-[10px] font-extrabold uppercase tracking-wide text-[#7890ab]">Starting point</p><p className="mt-1 text-sm font-bold">Written business details</p></div><div className="rounded-xl border border-[#e3eaf2] p-3"><p className="text-[10px] font-extrabold uppercase tracking-wide text-[#7890ab]">Next step</p><p className="mt-1 text-sm font-bold">Your review—not a launch</p></div></div>
          </div>
        </div>
      </section>
      <section id="how-it-works" className="border-y border-[#e3eaf2] bg-white"><div className="mx-auto max-w-7xl px-5 py-16 lg:px-10 lg:py-20"><p className="text-xs font-extrabold uppercase tracking-[.18em] text-[#2674e9]">A steady first step</p><h2 className="mt-3 max-w-2xl font-display text-3xl font-extrabold tracking-[-.045em] sm:text-4xl">From business details to a draft you can understand.</h2><div className="mt-10 grid gap-7 md:grid-cols-3">{[['01','Start with what you know','Describe your business, what you offer, and who you serve.'],['02','Get three directions','Dummy uses clear writing rules to turn your details into editable concepts.'],['03','Review before anything else','Save your draft and check every detail. No campaign is launched from AdPilot.']].map(([n,t,d])=><div key={n} className="border-t-2 border-[#176ff0] pt-5"><span className="font-mono text-xs font-bold text-[#176ff0]">{n}</span><h3 className="mt-4 font-display text-lg font-extrabold">{t}</h3><p className="mt-2 text-sm leading-6 text-[#5a6d86]">{d}</p></div>)}</div></div></section>
      <section className="mx-auto max-w-7xl px-5 py-14 lg:px-10"><div className="grid gap-8 rounded-[28px] bg-[#142d50] px-6 py-9 text-white md:grid-cols-[1fr_auto] md:items-center md:px-10 md:py-12"><div><p className="text-xs font-extrabold uppercase tracking-[.18em] text-[#80b3ff]">Clear limits. No surprises.</p><h2 className="mt-3 max-w-2xl font-display text-2xl font-extrabold tracking-[-.04em] sm:text-3xl">You stay in charge of what happens next.</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-blue-100/75">Dummy is a placeholder for transparent, rule-based drafting. It is not ChatGPT, does not inspect files, and cannot launch ads. Your media stays local to this browser.</p></div><Link href="/sign-up" className="inline-flex min-h-11 w-fit items-center gap-2 rounded-xl bg-white px-5 text-sm font-bold text-[#142d50] hover:bg-blue-50" data-testid="link-start-free">Start with your business <ArrowRight size={16}/></Link></div></section>
    </main>
    <footer className="border-t border-[#e3eaf2] bg-white px-5 py-6"><div className="mx-auto flex max-w-7xl flex-col justify-between gap-2 text-xs font-medium text-[#63758b] sm:flex-row lg:px-10"><span>AdPilot · A workspace for a more thoughtful first ad.</span><span>No connected ad accounts. Nothing launches here.</span></div></footer>
  </div>;
}

function WorkspaceShell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [mobileOpen,setMobileOpen] = useState(false);
  const { signOut } = useClerk();
  return <div className="min-h-[100dvh] bg-[#f3f6fa]">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[252px] flex-col bg-[#142d50] text-white transition-transform duration-200 md:translate-x-0 ${mobileOpen?'translate-x-0':'-translate-x-full'}`}>
      <div className="flex h-[76px] items-center justify-between px-6"><Link href="/dashboard" className="flex items-center gap-3 font-display text-lg font-extrabold tracking-[-.03em]" data-testid="link-sidebar-brand"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#3186ff] text-sm font-bold">D</span>AdPilot</Link><button className="rounded-lg p-2 text-blue-100 md:hidden" onClick={()=>setMobileOpen(false)} aria-label="Close navigation" data-testid="button-close-navigation"><X size={18}/></button></div>
      <div className="mx-4 mb-5 rounded-xl border border-white/10 bg-white/[.06] p-3"><p className="text-[10px] font-extrabold uppercase tracking-[.15em] text-blue-200/70">Your workspace</p><p className="mt-1 truncate text-sm font-bold">Business starter</p></div>
      <nav className="space-y-1 px-3">{NAV.map(({href,label,icon:Icon})=>{const active=location===href || (href==='/campaigns'&&location.startsWith('/campaigns')); return <Link key={href} href={href} onClick={()=>setMobileOpen(false)} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold transition ${active?'bg-white text-[#142d50] shadow-sm':'text-blue-100/80 hover:bg-white/10 hover:text-white'}`} data-testid={`link-nav-${href.slice(1)}`}><Icon size={17}/>{label}{active&&<span className="ml-auto h-1.5 w-1.5 rounded-full bg-[#2582ff]"/>}</Link>;})}</nav>
      <div className="mt-auto p-4"><div className="mb-3 rounded-xl border border-white/10 bg-white/[.06] p-3"><div className="flex items-center gap-2 text-xs font-bold"><CloudOff size={15} className="text-blue-200"/>Ad accounts disconnected</div><p className="mt-1 text-[11px] leading-4 text-blue-100/65">Nothing is running. Connectors are not available yet.</p></div><button onClick={()=>signOut({redirectUrl:basePath||'/'})} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold text-blue-100/80 hover:bg-white/10 hover:text-white" data-testid="button-sign-out"><LogOut size={16}/>Sign out</button></div>
    </aside>
    {mobileOpen&&<button className="fixed inset-0 z-30 bg-[#10213c]/40 md:hidden" onClick={()=>setMobileOpen(false)} aria-label="Close navigation overlay" data-testid="button-navigation-overlay"/>}
    <div className="md:pl-[252px]"><header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-[#e2e9f1] bg-white/90 px-4 backdrop-blur-md sm:px-7"><div className="flex items-center gap-3"><button className="rounded-lg p-2 text-[#34506f] hover:bg-[#f1f5f9] md:hidden" onClick={()=>setMobileOpen(true)} aria-label="Open navigation" data-testid="button-open-navigation"><Menu size={19}/></button><span className="hidden text-xs font-semibold text-slate-500 sm:block">Your workspace</span><ChevronRight className="hidden text-slate-300 sm:block" size={15}/><span className="text-sm font-bold text-[#203756]">{NAV.find((n)=>location===n.href)?.label ?? (location==='/campaigns/new'?'New campaign':location.startsWith('/campaigns/')?'Campaign draft':'AdPilot')}</span></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-full border border-[#e1e8f0] px-3 py-1.5 text-[11px] font-semibold text-slate-600 sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-amber-500"/>Drafts only</div><span className="grid h-8 w-8 place-items-center rounded-full bg-[#e7f0ff] text-xs font-extrabold text-[#176ff0]" data-testid="text-user-avatar">AP</span></div></header><main className="mx-auto max-w-[1440px] px-4 py-7 sm:px-7 lg:px-10 lg:py-9"><div className="page-enter">{children}</div></main></div>
  </div>;
}

function DashboardPage() {
  const query=useGetDashboardSummary();
  const summary=query.data;
  return <><PageHead eyebrow="Your workspace" title="A good place to begin." detail="Keep your campaign ideas and business details in one clear place." action={<Link href="/campaigns/new" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-[#176ff0] px-4 text-sm font-bold text-white hover:bg-[#0d5fd7]" data-testid="link-new-campaign"><Plus size={17}/>Start a campaign</Link>}/>
    {query.isLoading?<div className="grid gap-4 sm:grid-cols-3"><Skeleton className="h-32"/><Skeleton className="h-32"/><Skeleton className="h-32"/></div>:query.isError?<ErrorPanel retry={()=>query.refetch()}/>:<><div className="grid gap-4 sm:grid-cols-3">{[['Total campaigns',summary?.campaignCount??0,BarChart3,'All of your saved drafts'],['Drafts',summary?.draftCount??0,Pencil,'Still being put together'],['Ready for review',summary?.reviewCount??0,ShieldCheck,'Waiting for a person to check']].map(([title,count,Icon,sub])=>{const IconComponent=Icon as LucideIcon;return <div key={String(title)} className="rounded-2xl border border-[#e1e8f0] bg-white p-5 shadow-[0_3px_12px_rgba(27,52,82,.025)]"><div className="flex items-start justify-between"><div><p className="text-sm font-semibold text-slate-500">{title as string}</p><p className="mt-3 font-display text-4xl font-extrabold tracking-[-.05em] text-[#183252]" data-testid={`value-${String(title).toLowerCase().replaceAll(' ','-')}`}>{count as number}</p></div><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#edf4ff] text-[#2875e8]"><IconComponent size={18}/></span></div><p className="mt-3 text-xs font-medium text-slate-500">{sub as string}</p></div>})}</div>
      <div className="mt-8 grid gap-6 xl:grid-cols-[1.45fr_.75fr]"><section className="rounded-2xl border border-[#e1e8f0] bg-white"><div className="flex items-center justify-between border-b border-[#edf1f5] px-5 py-4"><div><h2 className="font-display text-lg font-extrabold">Recent drafts</h2><p className="mt-1 text-xs text-slate-500">Pick up where you left off.</p></div><Link href="/campaigns" className="text-xs font-bold text-[#176ff0] hover:underline" data-testid="link-all-campaigns">All campaigns <ArrowRight className="ml-1 inline" size={14}/></Link></div>
        {summary?.recentCampaigns?.length ? <div className="divide-y divide-[#edf1f5]">{summary.recentCampaigns.slice(0,5).map(c=><CampaignRow key={c.id} campaign={c}/>)}</div>:<div className="p-5"><EmptyPanel title="Your first idea starts here" body="When you save a campaign draft, it will appear in this list." action={<Link href="/campaigns/new" className="inline-flex items-center gap-2 rounded-xl bg-[#176ff0] px-4 py-2.5 text-sm font-bold text-white" data-testid="link-empty-create-campaign"><Plus size={15}/>Create a draft</Link>}/></div>}
      </section><section className="rounded-2xl bg-[#142d50] p-6 text-white"><div className="flex items-center gap-3 text-[#8dbbff]"><DummyVisual className="h-10 w-10 rounded-xl text-sm"/><span className="text-xs font-extrabold uppercase tracking-[.14em]">A note from Dummy</span></div><h2 className="mt-4 font-display text-xl font-extrabold leading-7">Good ads start with what makes your business yours.</h2><p className="mt-3 text-sm leading-6 text-blue-100/75">A few useful details make your three starter concepts more relevant. You can edit every one before saving.</p><Link href="/business" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-white hover:text-blue-200" data-testid="link-profile-from-dashboard">Check your business details <ArrowRight size={15}/></Link><div className="mt-8 border-t border-white/15 pt-4 text-xs leading-5 text-blue-100/65">Dummy applies simple writing rules to the text you provide. It is not an AI model and does not inspect file contents.</div></section></div>
    </>}
  </>;
}
function CampaignRow({campaign:c}:{campaign:Campaign}) {
  return <Link href={`/campaigns/${c.id}`} className="flex items-center justify-between gap-4 px-5 py-4 transition hover:bg-[#f7faff]" data-testid={`row-campaign-${c.id}`}><div className="min-w-0"><p className="truncate text-sm font-bold text-[#1e385a]" data-testid={`text-campaign-name-${c.id}`}>{c.name}</p><div className="mt-1.5 flex flex-wrap items-center gap-2 text-xs text-slate-500"><span>{objectiveLabel(c.objective)}</span><span aria-hidden="true">·</span><span>{c.platforms.map(platformLabel).join(', ')}</span></div></div><div className="flex shrink-0 items-center gap-3"><Tag tone={c.status==='ready_for_review'?'green':'gray'}>{statusLabel(c.status)}</Tag><ChevronRight size={16} className="text-slate-400"/></div></Link>;
}

function CampaignsPage() {
  const q=useListCampaigns(); const [search,setSearch]=useState('');
  const all=q.data??[]; const rows=useMemo(()=>all.filter(c=>c.name.toLowerCase().includes(search.toLowerCase())),[all,search]);
  return <><PageHead eyebrow="Campaign workspace" title="Campaigns" detail="Your saved concepts, clearly marked as drafts or ready for your review." action={<Link href="/campaigns/new" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-[#176ff0] px-4 text-sm font-bold text-white" data-testid="link-new-campaign"><Plus size={17}/>New campaign</Link>}/>
    <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="relative w-full max-w-sm"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/><TextInput value={search} onChange={e=>setSearch(e.target.value)} placeholder="Find a campaign" className="pl-9" aria-label="Find a campaign" data-testid="input-campaign-search"/></div><p className="text-xs font-medium text-slate-500" data-testid="value-campaign-count">{rows.length} {rows.length===1?'campaign':'campaigns'}</p></div>
    {q.isLoading?<div className="space-y-3"><Skeleton className="h-20"/><Skeleton className="h-20"/><Skeleton className="h-20"/></div>:q.isError?<ErrorPanel retry={()=>q.refetch()}/>:rows.length?<div className="overflow-hidden rounded-2xl border border-[#e1e8f0] bg-white">{rows.map(c=><CampaignRow key={c.id} campaign={c}/>)}</div>:<EmptyPanel title={search?'No matching campaigns':'No campaigns saved yet'} body={search?'Try another search term.':'Create your first campaign draft. Dummy will create three editable concepts from your written details.'} action={!search&&<Link href="/campaigns/new" className="inline-flex items-center gap-2 rounded-xl bg-[#176ff0] px-4 py-2.5 text-sm font-bold text-white" data-testid="link-empty-create-campaign"><Plus size={15}/>Create a draft</Link>}/>}
    <p className="mt-5 flex items-center gap-2 text-xs leading-5 text-slate-500"><CircleHelp size={14}/>Ready for your review means a person needs to review it. It does not mean an ad is running.</p></>;
}

const emptyProfile: BusinessProfileInput = {
  businessName:'', businessDescription:'', productsServices:'', websiteUrl:null, businessLocation:'',
  advertisingLocations:[], targetAudience:'', language:'English', objective:'enquiries', brandColors:[],
   preferredTone:'Clear and friendly', currency:'NGN', timeZone:'Africa/Lagos', dailyBudget:null, totalBudget:null,
  startDate:null, endDate:null,
};
function profileToInput(p?: BusinessProfile): BusinessProfileInput {
  if(!p)return {...emptyProfile};
  const {updatedAt:_updated,...input}=p; return input;
}
function BusinessPage() {
  const query=useGetBusinessProfile(); const save=useSaveBusinessProfile(); const qc=useQueryClient();
  const [form,setForm]=useState<BusinessProfileInput>({...emptyProfile}); const [places,setPlaces]=useState('');
  useEffect(()=>{if(query.data){const input=profileToInput(query.data);setForm(input);setPlaces(input.advertisingLocations.join(', '));}},[query.data]);
  const set=<K extends keyof BusinessProfileInput>(key:K,value:BusinessProfileInput[K])=>setForm(s=>({...s,[key]:value}));
  function submit(e:FormEvent){e.preventDefault();save.mutate({data:{...form,advertisingLocations:places.split(',').map(x=>x.trim()).filter(Boolean),brandColors:form.brandColors}}, {onSuccess:()=>{qc.invalidateQueries({queryKey:getGetBusinessProfileQueryKey()});}});}
  return <><PageHead eyebrow="Your foundation" title="Business profile" detail="Tell Dummy what your business does. These written details help shape the campaign concepts."/>
    {query.isLoading?<div className="space-y-3"><Skeleton className="h-20"/><Skeleton className="h-64"/></div>:<form onSubmit={submit} className="max-w-4xl">
      {query.isError&&<div className="mb-4"><ErrorPanel retry={()=>query.refetch()} message="We could not load saved profile details. You can still enter them below." /></div>}
      <div className="rounded-2xl border border-[#e1e8f0] bg-white p-5 sm:p-7"><div className="mb-6 border-b border-[#edf1f5] pb-4"><h2 className="font-display text-lg font-extrabold">About your business</h2><p className="mt-1 text-sm text-slate-500">A few specifics beat polished marketing language.</p></div>
        <div className="grid gap-5 sm:grid-cols-2"><Field label="Business name"><TextInput required maxLength={160} value={form.businessName} onChange={e=>set('businessName',e.target.value)} placeholder="The name customers know" data-testid="input-business-name"/></Field><Field label="Website" help="Optional"><TextInput type="url" value={form.websiteUrl??''} onChange={e=>set('websiteUrl',e.target.value||null)} placeholder="https://" data-testid="input-business-website"/></Field>
          <Field label="Where is your business based?"><TextInput value={form.businessLocation} onChange={e=>set('businessLocation',e.target.value)} placeholder="Town, city, or region" data-testid="input-business-location"/></Field><Field label="Where do you want to advertise?" help="Separate places with a comma"><TextInput value={places} onChange={e=>setPlaces(e.target.value)} placeholder="Neighbourhood, city, region" data-testid="input-advertising-locations"/></Field>
          <div className="sm:col-span-2"><Field label="What does your business do?" help="Describe it in your own words. Up to 2,000 characters."><TextArea maxLength={2000} value={form.businessDescription} onChange={e=>set('businessDescription',e.target.value)} placeholder="We help..." data-testid="input-business-description"/></Field></div>
          <div className="sm:col-span-2"><Field label="What products or services do you offer?"><TextArea maxLength={2000} value={form.productsServices} onChange={e=>set('productsServices',e.target.value)} placeholder="List the products or services you want people to know about." data-testid="input-products-services"/></Field></div>
          <div className="sm:col-span-2"><Field label="Who do you want to reach?"><TextArea maxLength={1000} value={form.targetAudience} onChange={e=>set('targetAudience',e.target.value)} placeholder="Describe the people who are most likely to need what you offer." data-testid="input-target-audience"/></Field></div>
        </div>
      </div>
      <div className="mt-5 rounded-2xl border border-[#e1e8f0] bg-white p-5 sm:p-7"><div className="mb-6 border-b border-[#edf1f5] pb-4"><h2 className="font-display text-lg font-extrabold">Campaign preferences</h2><p className="mt-1 text-sm text-slate-500">Starting points only. You can change these in each campaign.</p></div>
        <div className="grid gap-5 sm:grid-cols-2"><Field label="Main goal"><SelectInput value={form.objective} onChange={e=>set('objective',e.target.value as CampaignObjective)} data-testid="select-business-objective">{OBJECTIVES.map(x=><option key={x.value} value={x.value}>{x.label}</option>)}</SelectInput></Field><Field label="Preferred writing tone"><TextInput value={form.preferredTone} onChange={e=>set('preferredTone',e.target.value)} placeholder="Clear and friendly" data-testid="input-preferred-tone"/></Field><Field label="Language"><TextInput value={form.language} onChange={e=>set('language',e.target.value)} data-testid="input-language"/></Field><Field label="Currency"><TextInput maxLength={8} value={form.currency} onChange={e=>set('currency',e.target.value)} data-testid="input-currency"/></Field><Field label="Daily budget (optional)"><TextInput type="number" min="0" step="0.01" value={form.dailyBudget??''} onChange={e=>set('dailyBudget',e.target.value?Number(e.target.value):null)} placeholder="Not set" data-testid="input-daily-budget"/></Field><Field label="Total budget (optional)"><TextInput type="number" min="0" step="0.01" value={form.totalBudget??''} onChange={e=>set('totalBudget',e.target.value?Number(e.target.value):null)} placeholder="Not set" data-testid="input-total-budget"/></Field><Field label="Time zone"><TextInput value={form.timeZone} onChange={e=>set('timeZone',e.target.value)} placeholder="e.g. America/Chicago" data-testid="input-time-zone"/></Field><Field label="Brand colors" help="Comma-separated color names or hex values"><TextInput value={form.brandColors.join(', ')} onChange={e=>set('brandColors',e.target.value.split(',').map(s=>s.trim()).filter(Boolean))} placeholder="Navy, #176FF0" data-testid="input-brand-colors"/></Field></div>
      </div><div className="mt-5 flex flex-wrap items-center justify-between gap-3"><span className="text-xs text-slate-500" data-testid="text-profile-updated">{query.data?`Last updated ${new Date(query.data.updatedAt).toLocaleDateString()}`:'Your changes are saved to your profile when you choose Save.'}</span><Button type="submit" disabled={save.isPending} data-testid="button-save-profile">{save.isPending?<LoaderCircle className="animate-spin" size={16}/>:<Save size={16}/>}Save business profile</Button></div>
      {save.isError&&<p className="mt-3 text-sm font-semibold text-red-700" data-testid="status-profile-error">We could not save your profile. Please try again.</p>}
    </form>}
  </>;
}

type LocalMedia={id:string;ownerId:string;name:string;type:string;size:number;description:string;blob:Blob;addedAt:string};
type DummyWelcomeAsset={id:string;ownerId:string;name:string;type:string;size:number;blob:Blob;addedAt:string};
const MEDIA_DB='adpilot-browser-media'; const MEDIA_STORE='selected-files';
const DUMMY_WELCOME_PREFIX='dummy-welcome:';
function openMediaDb():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{const request=indexedDB.open(MEDIA_DB,1);request.onupgradeneeded=()=>request.result.createObjectStore(MEDIA_STORE,{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function readMedia(ownerId:string):Promise<LocalMedia[]>{const db=await openMediaDb();return new Promise((resolve,reject)=>{const r=db.transaction(MEDIA_STORE,'readonly').objectStore(MEDIA_STORE).getAll();r.onsuccess=()=>resolve((r.result as LocalMedia[]).filter(item=>item.ownerId===ownerId&&!item.id.startsWith(DUMMY_WELCOME_PREFIX)));r.onerror=()=>reject(r.error);});}
async function writeMedia(items:LocalMedia[],ownerId:string){const db=await openMediaDb();await new Promise<void>((resolve,reject)=>{const tx=db.transaction(MEDIA_STORE,'readwrite');const store=tx.objectStore(MEDIA_STORE);items.forEach(x=>store.put({...x,ownerId}));tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
async function removeMedia(id:string){const db=await openMediaDb();await new Promise<void>((resolve,reject)=>{const tx=db.transaction(MEDIA_STORE,'readwrite');tx.objectStore(MEDIA_STORE).delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
async function readDummyWelcome(ownerId:string):Promise<DummyWelcomeAsset|null>{const db=await openMediaDb();return new Promise((resolve,reject)=>{const request=db.transaction(MEDIA_STORE,'readonly').objectStore(MEDIA_STORE).get(`${DUMMY_WELCOME_PREFIX}${ownerId}`);request.onsuccess=()=>resolve((request.result as DummyWelcomeAsset|undefined)??null);request.onerror=()=>reject(request.error);});}
async function writeDummyWelcome(ownerId:string,file:File):Promise<DummyWelcomeAsset>{const asset:DummyWelcomeAsset={id:`${DUMMY_WELCOME_PREFIX}${ownerId}`,ownerId,name:file.name,type:file.type,size:file.size,blob:file,addedAt:new Date().toISOString()};const db=await openMediaDb();await new Promise<void>((resolve,reject)=>{const tx=db.transaction(MEDIA_STORE,'readwrite');tx.objectStore(MEDIA_STORE).put(asset);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});return asset;}
async function removeDummyWelcome(ownerId:string){const db=await openMediaDb();await new Promise<void>((resolve,reject)=>{const tx=db.transaction(MEDIA_STORE,'readwrite');tx.objectStore(MEDIA_STORE).delete(`${DUMMY_WELCOME_PREFIX}${ownerId}`);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}

type DummyAssetContextValue={scope:string;asset:DummyWelcomeAsset|null;assetUrl:string|null;loading:boolean;error:string;saveAsset:(file:File)=>Promise<void>;removeAsset:()=>Promise<void>};
const DummyAssetContext=createContext<DummyAssetContextValue|null>(null);
export function DummyAssetProvider({userId,children}:{userId:string|null;children:ReactNode}){
  const scope=userId??'anonymous';const[asset,setAsset]=useState<DummyWelcomeAsset|null>(null);const[assetUrl,setAssetUrl]=useState<string|null>(null);const[loading,setLoading]=useState(true);const[error,setError]=useState('');
  useEffect(()=>{let active=true;setLoading(true);setError('');readDummyWelcome(scope).then(value=>{if(active)setAsset(value);}).catch(()=>{if(active)setError('This browser could not load Dummy’s local welcome asset.');}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[scope]);
  useEffect(()=>{if(!asset){setAssetUrl(null);return;}const url=URL.createObjectURL(asset.blob);setAssetUrl(url);return()=>URL.revokeObjectURL(url);},[asset]);
  async function saveAsset(file:File){if(!file.type.startsWith('image/')&&!file.type.startsWith('video/')){setError('Choose an image or video file.');return;}try{const saved=await writeDummyWelcome(scope,file);setAsset(saved);setError('');}catch{setError('The browser could not save this welcome asset. Try a smaller file or remove another local file.');}}
  async function removeAsset(){try{await removeDummyWelcome(scope);setAsset(null);setError('');}catch{setError('The browser could not remove this welcome asset.');}}
  const value=useMemo(()=>({scope,asset,assetUrl,loading,error,saveAsset,removeAsset}),[scope,asset,assetUrl,loading,error]);
  return <DummyAssetContext.Provider value={value}>{children}</DummyAssetContext.Provider>;
}
function useDummyAsset(){const value=useContext(DummyAssetContext);if(!value)throw new Error('DummyAssetProvider is missing.');return value;}
function DummyVisual({className='h-10 w-10'}:{className?:string}){
  const{asset,assetUrl,loading}=useDummyAsset();const frame=`grid shrink-0 place-items-center overflow-hidden bg-[#e4efff] font-bold text-[#176ff0] ${className}`;
  if(!asset||!assetUrl)return <span className={frame} role="img" aria-label={loading?'Loading Dummy welcome asset':'Dummy placeholder — upload a welcome image or video in Media library'} data-testid="dummy-welcome-visual">D</span>;
  if(asset.type.startsWith('image/'))return <img src={assetUrl} alt="User-selected welcome image for Dummy" className={`${frame} object-cover`} data-testid="dummy-welcome-visual"/>;
  return <video src={assetUrl} autoPlay muted loop playsInline aria-label="User-selected welcome video for Dummy" className={`${frame} object-cover`} data-testid="dummy-welcome-visual"/>;
}
function MediaPage() {
  const{scope,asset,error:assetError,saveAsset,removeAsset}=useDummyAsset();const [media,setMedia]=useState<LocalMedia[]>([]);const[loading,setLoading]=useState(true);const[error,setError]=useState(false);const[search,setSearch]=useState('');
  const reload=()=>{setLoading(true);readMedia(scope).then(setMedia).catch(()=>setError(true)).finally(()=>setLoading(false));};
  useEffect(()=>{reload();},[scope]);
  async function handleFiles(e:ChangeEvent<HTMLInputElement>){const files=Array.from(e.target.files??[]);if(!files.length)return;const items=files.map(file=>({id:crypto.randomUUID(),ownerId:scope,name:file.name,type:file.type,size:file.size,description:'',blob:file,addedAt:new Date().toISOString()}));try{await writeMedia(items,scope);reload();}catch{setError(true);}e.target.value='';}
  async function handleDummyFile(e:ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(file)await saveAsset(file);e.target.value='';}
  async function updateDescription(id:string,description:string){const updated=media.map(x=>x.id===id?{...x,description}:x);setMedia(updated);try{await writeMedia(updated,scope);}catch{setError(true);}}
  async function deleteFile(id:string){await removeMedia(id);setMedia(s=>s.filter(x=>x.id!==id));}
  const items=media.filter(x=>x.name.toLowerCase().includes(search.toLowerCase()));
  return <><PageHead eyebrow="Local to this browser" title="Media library" detail="Choose images or videos as references and write your own descriptions. Files are stored only in this browser, not uploaded." action={<label className="inline-flex min-h-11 cursor-pointer items-center gap-2 rounded-xl bg-[#176ff0] px-4 text-sm font-bold text-white hover:bg-[#0d5fd7]" data-testid="label-upload-media"><Upload size={16}/>Choose files<input className="sr-only" type="file" accept="image/*,video/*" multiple onChange={handleFiles} data-testid="input-upload-media" aria-label="Choose images or videos"/></label>}/>
    <div className="mb-5 flex flex-col gap-3 rounded-2xl border border-[#cfe1fa] bg-[#edf5ff] p-4 sm:flex-row sm:items-start"><ShieldCheck className="mt-0.5 shrink-0 text-[#2875e8]" size={18}/><div><p className="text-sm font-bold text-[#234e86]">Your files stay on this device</p><p className="mt-1 text-xs leading-5 text-[#47698f]">AdPilot stores selected media in your browser's IndexedDB. Dummy does not read, analyze, or upload file contents. Only descriptions you write may be used when drafting concepts.</p></div></div>
    <section className="mb-6 rounded-2xl border border-[#e1e8f0] bg-white p-5 sm:p-6" data-testid="section-dummy-welcome-asset"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-4"><DummyVisual className="h-16 w-16 rounded-2xl text-xl"/><div><h2 className="font-display text-lg font-extrabold">Dummy’s welcome image or video</h2><p className="mt-1 max-w-xl text-xs leading-5 text-slate-500">{asset?`${asset.name} · stored in this browser for this account.`:'Upload the image or welcome video you want to represent Dummy. It will appear beside Dummy throughout this workspace and on this browser’s landing page.'}</p></div></div><div className="flex flex-wrap gap-2"><label className="inline-flex min-h-10 cursor-pointer items-center gap-2 rounded-xl bg-[#176ff0] px-4 text-xs font-bold text-white hover:bg-[#0d5fd7]" data-testid="label-upload-dummy-welcome"><Upload size={15}/>{asset?'Choose a different file':'Choose image or video'}<input className="sr-only" type="file" accept="image/*,video/*" onChange={handleDummyFile} data-testid="input-dummy-welcome-asset" aria-label="Choose Dummy’s welcome image or video"/></label>{asset&&<Button variant="secondary" onClick={removeAsset} data-testid="button-remove-dummy-welcome">Remove</Button>}</div></div>{assetError&&<p className="mt-3 text-xs font-semibold text-amber-800" role="status" data-testid="status-dummy-welcome-error">{assetError}</p>}</section>
    <div className="mb-4 flex items-center justify-between gap-4"><div className="relative max-w-sm flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/><TextInput value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search local files" className="pl-9" data-testid="input-media-search"/></div><span className="text-xs font-semibold text-slate-500" data-testid="value-local-media-count">{media.length} local {media.length===1?'file':'files'}</span></div>
    {error&&<ErrorPanel retry={reload} message="This browser could not access its local media library."/>}
    {loading?<div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{[1,2,3].map(i=><Skeleton key={i} className="h-56"/>)}</div>:items.length?<div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{items.map(file=><article key={file.id} className="overflow-hidden rounded-2xl border border-[#e1e8f0] bg-white" data-testid={`card-media-${file.id}`}><div className="flex h-32 items-center justify-center bg-[#edf3fa]">{file.type.startsWith('image/')?<img src={URL.createObjectURL(file.blob)} alt="" className="h-full w-full object-cover"/>:file.type.startsWith('video/')?<FileVideo size={32} className="text-[#6681a2]"/>:<FileImage size={32} className="text-[#6681a2]"/>}</div><div className="p-4"><div className="flex items-start justify-between gap-2"><div className="min-w-0"><p className="truncate text-sm font-bold" data-testid={`text-media-name-${file.id}`}>{file.name}</p><p className="mt-1 text-xs text-slate-500">{file.type||'File'} · {Math.max(1,Math.round(file.size/1024))} KB</p></div><button className="rounded-lg p-2 text-slate-400 hover:bg-red-50 hover:text-red-700" title="Remove file" onClick={()=>deleteFile(file.id)} data-testid={`button-remove-media-${file.id}`}><Trash2 size={15}/></button></div><label className="mt-4 grid gap-1 text-xs font-bold text-slate-600">Your description<TextArea value={file.description} onChange={e=>updateDescription(file.id,e.target.value)} rows={2} placeholder="Describe the image or video in your own words" className="min-h-[68px] text-xs" data-testid={`input-media-description-${file.id}`}/></label></div></article>)}</div>:<EmptyPanel title={search?'No files match your search':'No media selected yet'} body="Choose an image or video from this device. It stays in browser storage, and Dummy will only use the description you write." action={<label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-[#dce5f0] bg-white px-4 py-2.5 text-sm font-bold text-[#183252]" data-testid="label-empty-upload"><ImagePlus size={16}/>Choose media<input className="sr-only" type="file" accept="image/*,video/*" multiple onChange={handleFiles} data-testid="input-empty-upload"/></label>}/>}
  </>;
}

function ConnectionsPage() {
  return <><PageHead eyebrow="Account connections" title="No ad accounts connected" detail="AdPilot helps prepare drafts. There is no live advertising account connected, and this workspace cannot launch ads."/>
    <div className="mb-6 rounded-2xl border border-amber-200 bg-amber-50 p-5"><div className="flex gap-3"><CloudOff className="mt-0.5 text-amber-700" size={20}/><div><p className="font-bold text-amber-950">Connections are unavailable</p><p className="mt-1 text-sm leading-6 text-amber-900/80">Connecting Google, Meta, or TikTok accounts is not supported here. These platforms remain disconnected.</p></div></div></div>
    <div className="grid max-w-4xl gap-4 md:grid-cols-3">{PLATFORMS.map((p,i)=>{const Logo=i===0?Globe2:i===1?MessageSquareText:FileVideo;return <div key={p.value} className="rounded-2xl border border-[#e1e8f0] bg-white p-5" data-testid={`card-connection-${p.value}`}><div className="flex items-start justify-between"><span className="grid h-11 w-11 place-items-center rounded-xl bg-[#edf4ff] text-[#2875e8]"><Logo size={20}/></span><Tag tone="gray">Not connected</Tag></div><h2 className="mt-5 font-display text-lg font-extrabold">{p.label}</h2><p className="mt-1 text-xs text-slate-500">{p.note}</p><button type="button" disabled className="mt-5 flex min-h-10 w-full items-center justify-center gap-2 rounded-xl border border-[#e1e8f0] bg-[#f6f8fb] text-xs font-bold text-slate-500" data-testid={`button-connect-${p.value}`}><CloudOff size={14}/>Connection unavailable</button></div>})}</div>
    <p className="mt-5 max-w-4xl text-xs leading-5 text-slate-500">Concepts created for these platforms are suggestions only. They do not publish or activate anything.</p>
  </>;
}

function ConceptCard({concept,index,onChange,onRevise,revisionPending}:{concept:CampaignConcept;index:number;onChange:(c:CampaignConcept)=>void;onRevise:(direction:'shorter'|'warmer'|'clearer'|'different_angle')=>void;revisionPending:boolean}) {
  const [showDetails,setShowDetails]=useState(false);
  const set=<K extends keyof CampaignConcept>(key:K,value:CampaignConcept[K])=>onChange({...concept,[key]:value});
  return <article className="overflow-hidden rounded-2xl border border-[#dfe7f0] bg-white" data-testid={`card-concept-${index+1}`}><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#edf1f5] bg-[#fafcff] px-5 py-4"><div className="flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#e8f1ff] text-xs font-extrabold text-[#176ff0]">{String(index+1).padStart(2,'0')}</span><div><p className="text-sm font-extrabold text-[#1c3758]" data-testid={`text-concept-angle-${index+1}`}>{concept.angle||`Concept ${index+1}`}</p><p className="mt-0.5 text-[11px] font-medium text-slate-500">{platformLabel(concept.platform)} · Starter concept</p></div></div><button type="button" onClick={()=>setShowDetails(x=>!x)} className="inline-flex items-center gap-1 rounded-lg px-2.5 py-2 text-xs font-bold text-[#176ff0] hover:bg-blue-50" data-testid={`button-toggle-concept-details-${index+1}`}>{showDetails?'Hide details':'Audience & reasoning'}<ChevronDown size={14} className={showDetails?'rotate-180 transition':'transition'}/></button></div>
    <div className="grid gap-4 p-5 md:grid-cols-2"><Field label="Concept angle"><TextInput value={concept.angle} onChange={e=>set('angle',e.target.value)} data-testid={`input-concept-angle-${index+1}`}/></Field><Field label="Platform"><SelectInput value={concept.platform} onChange={e=>set('platform',e.target.value as CampaignPlatform)} data-testid={`select-concept-platform-${index+1}`}>{PLATFORMS.map(platform=><option key={platform.value} value={platform.value}>{platform.label}</option>)}</SelectInput></Field><Field label="Headline"><TextInput maxLength={180} value={concept.headline} onChange={e=>set('headline',e.target.value)} data-testid={`input-concept-headline-${index+1}`}/></Field><Field label="Call to action"><TextInput value={concept.callToAction} onChange={e=>set('callToAction',e.target.value)} data-testid={`input-concept-cta-${index+1}`}/></Field><div className="md:col-span-2"><Field label="Primary copy"><TextArea rows={3} value={concept.primaryCopy} onChange={e=>set('primaryCopy',e.target.value)} data-testid={`input-concept-copy-${index+1}`}/></Field></div>
      <div className="md:col-span-2"><Field label="Media description (optional)" help="Write what you would like to show. Dummy does not inspect selected file contents."><TextArea rows={2} value={concept.mediaDescription??''} onChange={e=>set('mediaDescription',e.target.value||null)} placeholder="Describe an image or scene in your own words" data-testid={`input-concept-media-${index+1}`}/></Field></div>
      {showDetails&&<div className="md:col-span-2 grid gap-3 rounded-xl bg-[#f5f8fc] p-4 sm:grid-cols-2"><Field label="Suggested audience"><TextInput value={concept.audience} onChange={e=>set('audience',e.target.value)} data-testid={`input-concept-audience-${index+1}`}/></Field><div><p className="text-[10px] font-extrabold uppercase tracking-wider text-slate-500">Why this direction</p><p className="mt-1 text-sm leading-5 text-[#314b6d]" data-testid={`text-concept-explanation-${index+1}`}>{concept.explanation}</p></div>{concept.storyboard!==null&&<div className="sm:col-span-2"><Field label="Story outline"><TextArea rows={2} value={concept.storyboard??''} onChange={e=>set('storyboard',e.target.value||null)} data-testid={`input-concept-storyboard-${index+1}`}/></Field></div>}</div>}
    </div>
    <div className="flex flex-col gap-3 border-t border-[#edf1f5] px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs font-semibold text-slate-500">Ask Dummy to revise with a writing direction</p><div className="flex flex-wrap gap-2">{([['shorter','Shorter'],['warmer','Warmer'],['clearer','Clearer'],['different_angle','Different angle']] as const).map(([direction,label])=><button key={direction} type="button" disabled={revisionPending} onClick={()=>onRevise(direction)} className="rounded-lg border border-[#dce5f0] px-2.5 py-1.5 text-xs font-bold text-[#344e6e] hover:border-[#a9c7ed] hover:bg-[#f4f8ff] disabled:opacity-50" data-testid={`button-revise-${direction}-${index+1}`}>{revisionPending?'Working…':label}</button>)}</div></div>
  </article>;
}

function CampaignBuilder({existing}:{existing?:Campaign}) {
  const [,setLocation]=useLocation();const queryClient=useQueryClient();const profileQ=useGetBusinessProfile();
  const {scope}=useDummyAsset();
  const generate=useGenerateCampaignIdeas();const revise=useReviseCampaignIdea();const create=useCreateCampaign();const update=useUpdateCampaign();
  const [name,setName]=useState(existing?.name??'');const [objective,setObjective]=useState<CampaignObjective>(existing?.objective??'enquiries');
  const [platforms,setPlatforms]=useState<CampaignPlatform[]>(existing?.platforms??['meta']);const [budget,setBudget]=useState<number|null>(existing?.budget??null);
  const [currency,setCurrency]=useState(existing?.currency??'NGN');const [currencyWasEdited,setCurrencyWasEdited]=useState(Boolean(existing));const [startDate,setStartDate]=useState(existing?.startDate??'');const [endDate,setEndDate]=useState(existing?.endDate??'');
  const [concepts,setConcepts]=useState<CampaignConcept[]>(existing?.concepts??[]);const [media,setMedia]=useState<LocalMedia[]>([]);const [notice,setNotice]=useState('');const [step,setStep]=useState(existing?.concepts?.length?2:1);
  useEffect(()=>{if(existing){setName(existing.name);setObjective(existing.objective);setPlatforms(existing.platforms);setBudget(existing.budget);setCurrency(existing.currency);setStartDate(existing.startDate??'');setEndDate(existing.endDate??'');setConcepts(existing.concepts);setStep(2);}},[existing?.id]);
  const p=profileQ.data;
  useEffect(()=>{if(!existing&&p?.currency&&!currencyWasEdited)setCurrency(p.currency);},[existing?.id,p?.currency,currencyWasEdited]);
  useEffect(()=>{let active=true;readMedia(scope).then(value=>{if(active)setMedia(value);}).catch(()=>{if(active)setMedia([]);});return()=>{active=false;};},[scope]);
  const selectedFileDescriptions=media.map(m=>m.description.trim()).filter(Boolean);
  function togglePlatform(platform:CampaignPlatform){setPlatforms(s=>s.includes(platform)?s.filter(x=>x!==platform):[...s,platform]);}
  async function makeConcepts(){if(!p){setNotice('Add your business details first so Dummy has something useful to work from.');return;}if(platforms.length===0){setNotice('Choose at least one platform.');return;}
    const input={businessName:p.businessName,businessDescription:p.businessDescription,productsServices:p.productsServices,targetAudience:p.targetAudience,language:p.language,objective,preferredTone:p.preferredTone,platforms,mediaDescriptions:selectedFileDescriptions} as const;
    generate.mutate({data:input},{onSuccess:(response)=>{setConcepts(response.concepts);setNotice(response.notice);setStep(2);},onError:()=>setNotice('The concepts could not be drafted. Please try again.')});
  }
  function reviseConcept(index:number,direction:'shorter'|'warmer'|'clearer'|'different_angle'){const concept=concepts[index];revise.mutate({data:{concept,direction,businessName:p?.businessName??'',productsServices:p?.productsServices??''}},{onSuccess:(next)=>setConcepts(s=>s.map((c,i)=>i===index?next:c)),onError:()=>setNotice('That revision did not work. Your current concept is unchanged.')});}
  function saveCampaign(status:'draft'|'ready_for_review'){if(!name.trim()){setNotice('Give this campaign a name before saving.');return;}if(concepts.length!==3){setNotice('Draft the three concepts before saving.');return;}if(platforms.length===0){setNotice('Choose at least one platform before saving.');return;}
    const common={name:name.trim(),objective,platforms,budget,currency,startDate:startDate||null,endDate:endDate||null,concepts,status};
    if(existing){update.mutate({campaignId:existing.id,data:common},{onSuccess:async()=>{await Promise.all([queryClient.invalidateQueries({queryKey:getListCampaignsQueryKey()}),queryClient.invalidateQueries({queryKey:getGetCampaignQueryKey(existing.id)}),queryClient.invalidateQueries({queryKey:getGetDashboardSummaryQueryKey()})]);setNotice(status==='draft'?'Draft saved.':'Saved as ready for your review.');},onError:()=>setNotice('Could not save your changes. Please try again.')});}
    else create.mutate({data:common},{onSuccess:async(campaign)=>{await Promise.all([queryClient.invalidateQueries({queryKey:getListCampaignsQueryKey()}),queryClient.invalidateQueries({queryKey:getGetDashboardSummaryQueryKey()})]);setLocation(`/campaigns/${campaign.id}`);},onError:()=>setNotice('Could not save this campaign. Please try again.')});
  }
  const busy=generate.isPending||create.isPending||update.isPending;
  return <><PageHead eyebrow={existing?'Edit saved draft':'Guided setup'} title={existing?existing.name:'Build a campaign draft'} detail="Go one step at a time. Your three starter concepts are editable, and nothing is published from here."/>
    <div className="mb-6 flex items-center gap-2 text-xs font-bold text-slate-500"><span className={`flex items-center gap-2 ${step===1?'text-[#176ff0]':''}`}><span className="grid h-6 w-6 place-items-center rounded-full bg-[#eaf2ff] text-[11px] text-[#176ff0]">1</span>Set up</span><span className="h-px w-7 bg-slate-300"/><span className={`flex items-center gap-2 ${step===2?'text-[#176ff0]':''}`}><span className="grid h-6 w-6 place-items-center rounded-full bg-[#eaf2ff] text-[11px] text-[#176ff0]">2</span>Shape and review</span></div>
    {step===1&&<div className="max-w-4xl">
      <section className="rounded-2xl border border-[#e1e8f0] bg-white p-5 sm:p-7"><h2 className="font-display text-lg font-extrabold">Campaign basics</h2><p className="mt-1 text-sm text-slate-500">Choose the goal and platforms. These are suggestions, not connected accounts.</p><div className="mt-5 grid gap-5 sm:grid-cols-2"><Field label="Campaign name"><TextInput value={name} onChange={e=>setName(e.target.value)} maxLength={180} placeholder="A name you'll recognize" data-testid="input-campaign-name"/></Field><Field label="What should this campaign help with?"><SelectInput value={objective} onChange={e=>setObjective(e.target.value as CampaignObjective)} data-testid="select-campaign-objective">{OBJECTIVES.map(x=><option key={x.value} value={x.value}>{x.label}</option>)}</SelectInput></Field>
        <div className="sm:col-span-2"><Field label="Where would you like to advertise?"><div className="mt-1 grid gap-2 sm:grid-cols-3">{PLATFORMS.map(pf=><label key={pf.value} className={`flex cursor-pointer items-start gap-3 rounded-xl border p-3.5 transition ${platforms.includes(pf.value)?'border-[#83b3f6] bg-[#f2f7ff]':'border-[#e2e9f1] hover:bg-slate-50'}`}><input type="checkbox" checked={platforms.includes(pf.value)} onChange={()=>togglePlatform(pf.value)} className="mt-1 accent-[#176ff0]" data-testid={`checkbox-platform-${pf.value}`}/><span><span className="block text-sm font-bold">{pf.label}</span><span className="mt-1 block text-[11px] leading-4 text-slate-500">{pf.note} · not connected</span></span></label>)}</div></Field></div>
        <Field label={`Budget (${currency})`} help="Optional planning amount only. This does not spend or reserve money."><TextInput type="number" min="0" step=".01" value={budget??''} onChange={e=>setBudget(e.target.value?Number(e.target.value):null)} placeholder="Leave blank if undecided" data-testid="input-campaign-budget"/></Field><Field label="Currency"><TextInput maxLength={8} value={currency} onChange={e=>{setCurrencyWasEdited(true);setCurrency(e.target.value)}} data-testid="input-campaign-currency"/></Field><Field label="Start date (optional)"><TextInput type="date" value={startDate??''} onChange={e=>setStartDate(e.target.value)} data-testid="input-campaign-start-date"/></Field><Field label="End date (optional)"><TextInput type="date" value={endDate??''} onChange={e=>setEndDate(e.target.value)} data-testid="input-campaign-end-date"/></Field>
      </div></section>
      <section className="mt-5 rounded-2xl border border-[#e1e8f0] bg-white p-5 sm:p-7"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h2 className="font-display text-lg font-extrabold">Optional media descriptions</h2><p className="mt-1 max-w-xl text-sm leading-6 text-slate-500">Pick local files in Media library and write descriptions. Dummy uses descriptions only, never file contents.</p></div><Link href="/media" className="inline-flex min-h-10 items-center gap-2 rounded-xl border border-[#dce5f0] px-3 text-xs font-bold text-[#284666]" data-testid="link-open-media"><ImagePlus size={15}/>Open media library</Link></div>
        {media.length?<div className="mt-5 grid gap-3">{media.map((file,index)=><Field key={file.id} label={file.name}><TextArea value={file.description} onChange={e=>{const list=media.map(x=>x.id===file.id?{...x,description:e.target.value}:x);setMedia(list);writeMedia(list,scope);}} rows={2} placeholder={`Describe file ${index+1} in your own words`} data-testid={`input-builder-media-description-${file.id}`}/></Field>)}</div>:<p className="mt-4 rounded-xl bg-[#f5f8fc] px-4 py-3 text-xs font-medium text-slate-500" data-testid="text-no-selected-media">No local media selected. You can continue without media.</p>}
      </section>
      <div className="mt-5 flex flex-col gap-3 rounded-2xl border border-[#cfe1fa] bg-[#edf5ff] p-4 sm:flex-row"><DummyVisual className="h-9 w-9 rounded-xl text-sm"/><p className="text-xs leading-5 text-[#365a84]"><strong>About Dummy:</strong> it uses simple, deterministic writing rules on your written business details and optional file descriptions. It is not ChatGPT or an AI model, and it does not inspect uploaded file contents.</p></div>
      {notice&&<p className="mt-4 rounded-xl bg-amber-50 px-4 py-3 text-sm font-semibold text-amber-900" role="status" data-testid="status-builder-notice">{notice}</p>}
      {!p&&!profileQ.isLoading&&<div className="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900" data-testid="status-profile-needed">Add your business details before creating concepts. <Link href="/business" className="font-bold underline" data-testid="link-add-business-details">Complete business profile</Link></div>}
      <div className="mt-5 flex flex-wrap justify-end gap-3"><Button variant="secondary" onClick={()=>setLocation('/campaigns')} data-testid="button-cancel-builder">Cancel</Button><Button onClick={makeConcepts} disabled={busy||profileQ.isLoading} data-testid="button-generate-concepts">{generate.isPending?<LoaderCircle size={16} className="animate-spin"/>:<Sparkles size={16}/>}Create three concepts</Button></div>
      {generate.isError&&<ErrorPanel retry={makeConcepts} message="We could not create your concepts."/>}
    </div>}
    {step===2&&<div className="max-w-5xl"><div className="mb-5 flex flex-col justify-between gap-4 rounded-2xl border border-[#cfe1fa] bg-[#edf5ff] p-4 sm:flex-row sm:items-center"><p className="text-xs leading-5 text-[#365a84]" data-testid="text-rule-based-notice"><strong>Dummy made these with simple writing rules.</strong> They are editable starter ideas—not final ads. No media contents were inspected.</p><Button variant="secondary" onClick={()=>setStep(1)} data-testid="button-back-to-setup"><ChevronLeft size={15}/>Back to setup</Button></div>
      <div className="mb-5 grid gap-4 rounded-2xl border border-[#e1e8f0] bg-white p-5 sm:grid-cols-2 lg:grid-cols-3"><Field label="Campaign name"><TextInput value={name} onChange={e=>setName(e.target.value)} maxLength={180} placeholder="Give this draft a name" data-testid="input-review-campaign-name"/></Field><Field label="Campaign goal"><SelectInput value={objective} onChange={e=>setObjective(e.target.value as CampaignObjective)} data-testid="select-review-objective">{OBJECTIVES.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</SelectInput></Field><Field label={`Planning budget (${currency})`}><TextInput type="number" min="0" step=".01" value={budget??''} onChange={e=>setBudget(e.target.value?Number(e.target.value):null)} placeholder="Not set" data-testid="input-review-budget"/></Field><Field label="Start date"><TextInput type="date" value={startDate??''} onChange={e=>setStartDate(e.target.value)} data-testid="input-review-start-date"/></Field><Field label="End date"><TextInput type="date" value={endDate??''} onChange={e=>setEndDate(e.target.value)} data-testid="input-review-end-date"/></Field><div className="flex items-end"><div className="flex items-center gap-2 pb-2 text-xs font-bold text-slate-600"><Tag tone={existing?.status==='ready_for_review'?'green':'gray'}>{statusLabel(existing?.status??'draft')}</Tag><span>· Not running</span></div></div><div className="lg:col-span-3"><p className="mb-2 text-sm font-semibold text-[#203756]">Platforms <span className="ml-1 text-xs font-normal text-slate-500">No account connections are active</span></p><div className="flex flex-wrap gap-2">{PLATFORMS.map(pf=><label key={pf.value} className={`flex cursor-pointer items-center gap-2 rounded-xl border px-3 py-2 text-xs font-bold ${platforms.includes(pf.value)?'border-[#83b3f6] bg-[#f2f7ff] text-[#24579a]':'border-[#e2e9f1] text-slate-600'}`}><input type="checkbox" checked={platforms.includes(pf.value)} onChange={()=>togglePlatform(pf.value)} className="accent-[#176ff0]" data-testid={`checkbox-review-platform-${pf.value}`}/>{pf.label}</label>)}</div></div></div>
      <div className="space-y-4">{concepts.map((concept,i)=><ConceptCard key={`${i}-${concept.angle}`} concept={concept} index={i} onChange={c=>setConcepts(s=>s.map((x,j)=>j===i?c:x))} onRevise={direction=>reviseConcept(i,direction)} revisionPending={revise.isPending}/>)}</div>
      {notice&&<p className="mt-4 rounded-xl bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-900" role="status" data-testid="status-save-notice">{notice}</p>}
      <div className="mt-6 flex flex-col justify-between gap-4 rounded-2xl border border-[#e1e8f0] bg-white p-5 sm:flex-row sm:items-center"><p className="max-w-xl text-xs leading-5 text-slate-500">Saving as ready for review means you or someone on your team still needs to review it. It will not launch or connect to an ad account.</p><div className="flex flex-wrap gap-2"><Button variant="secondary" disabled={busy} onClick={()=>saveCampaign('draft')} data-testid="button-save-draft"><Save size={15}/>Save draft</Button><Button disabled={busy} onClick={()=>saveCampaign('ready_for_review')} data-testid="button-mark-review"><Check size={15}/>Save for review</Button></div></div>
      {create.isError||update.isError?<p className="mt-3 text-sm font-semibold text-red-700" data-testid="status-save-error">Your changes have not been saved. Please try again.</p>:null}
    </div>}
  </>;
}

function CampaignDetailPage({id}:{id:string}) {
  const q=useGetCampaign(id,{query:{queryKey:getGetCampaignQueryKey(id)}});const [editing,setEditing]=useState(false);const del=useDeleteCampaign();const qc=useQueryClient();const[,setLocation]=useLocation();
  if(q.isLoading)return <><Skeleton className="mb-5 h-10 w-1/3"/><Skeleton className="h-64"/></>;
  if(q.isError||!q.data)return <ErrorPanel retry={()=>q.refetch()} message="We could not open this campaign." />;
  const campaign=q.data;
  if(editing)return <><div className="mb-4"><Button variant="plain" onClick={()=>setEditing(false)} data-testid="button-close-edit"><ChevronLeft size={16}/>Back to campaign</Button></div><CampaignBuilder existing={campaign}/></>;
  async function remove(){if(!window.confirm('Delete this saved campaign draft? This cannot be undone.'))return;del.mutate({campaignId:id},{onSuccess:async()=>{await Promise.all([qc.invalidateQueries({queryKey:getListCampaignsQueryKey()}),qc.invalidateQueries({queryKey:getGetDashboardSummaryQueryKey()})]);setLocation('/campaigns');}});}
  return <><PageHead eyebrow="Saved campaign draft" title={campaign.name} detail="Review or edit the starter concepts. This saved draft is not connected to an ad account." action={<div className="flex gap-2"><Button variant="secondary" onClick={()=>setEditing(true)} data-testid="button-edit-campaign"><Pencil size={15}/>Edit draft</Button><Button variant="danger" disabled={del.isPending} onClick={remove} data-testid="button-delete-campaign"><Trash2 size={15}/>Delete</Button></div>}/>
    <div className="mb-5 grid gap-3 rounded-2xl border border-[#e1e8f0] bg-white p-5 sm:grid-cols-4">{[['Status',statusLabel(campaign.status)],['Objective',objectiveLabel(campaign.objective)],['Platforms',campaign.platforms.map(platformLabel).join(', ')],['Budget',campaign.budget==null?'Not set':`${currencyLabel(campaign.currency)} ${campaign.budget}`]].map(([k,v])=><div key={k}><p className="text-[10px] font-extrabold uppercase tracking-wider text-slate-500">{k}</p><p className="mt-1 text-sm font-bold text-[#294565]" data-testid={`value-campaign-${k.toLowerCase()}`}>{v}</p></div>)}</div>
    <div className="mb-5 flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 text-xs leading-5 text-amber-900"><CloudOff className="mt-0.5 shrink-0" size={16}/><p><strong>This campaign is not running.</strong> “Ready for your review” means a person still needs to review it. AdPilot cannot launch campaigns.</p></div>
    <div className="space-y-4">{campaign.concepts.map((concept,i)=><article key={i} className="rounded-2xl border border-[#e1e8f0] bg-white p-5" data-testid={`card-saved-concept-${i+1}`}><div className="mb-4 flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#e8f1ff] text-xs font-extrabold text-[#176ff0]">{String(i+1).padStart(2,'0')}</span><div><h2 className="font-display font-extrabold">{concept.angle}</h2><p className="mt-0.5 text-xs text-slate-500">{platformLabel(concept.platform)} · {concept.audience}</p></div></div><h3 className="text-lg font-extrabold text-[#1c3758]" data-testid={`text-saved-headline-${i+1}`}>{concept.headline}</h3><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600" data-testid={`text-saved-copy-${i+1}`}>{concept.primaryCopy}</p><div className="mt-4 flex flex-wrap gap-5 text-xs"><span><strong className="text-slate-500">Call to action</strong><span className="ml-2 font-bold text-[#294565]">{concept.callToAction}</span></span>{concept.mediaDescription&&<span><strong className="text-slate-500">Media</strong><span className="ml-2 text-[#294565]">{concept.mediaDescription}</span></span>}</div></article>)}</div>
    {del.isError&&<p className="mt-3 text-sm font-semibold text-red-700" data-testid="status-delete-error">Could not delete this draft. Try again.</p>}
  </>;
}

export function Workspace() {
  const [,setLocation]=useLocation();
  const [isDashboard]=useRoute('/dashboard'); const [isCampaigns]=useRoute('/campaigns'); const [isNew]=useRoute('/campaigns/new');
  const [isBusiness]=useRoute('/business'); const [isMedia]=useRoute('/media'); const [isConnections]=useRoute('/connections');
  const [matched,params]=useRoute('/campaigns/:campaignId');
  let body:ReactNode;
  if(isDashboard)body=<DashboardPage/>;
  else if(isCampaigns)body=<CampaignsPage/>;
  else if(isNew)body=<CampaignBuilder/>;
  else if(isBusiness)body=<BusinessPage/>;
  else if(isMedia)body=<MediaPage/>;
  else if(isConnections)body=<ConnectionsPage/>;
  else if(matched&&params?.campaignId)body=<CampaignDetailPage id={params.campaignId}/>;
  else body=<EmptyPanel title="Page not found" body="Choose a workspace area from the navigation to continue." action={<Link href="/dashboard" className="inline-flex rounded-xl bg-[#176ff0] px-4 py-2.5 text-sm font-bold text-white" data-testid="link-workspace-home">Go to overview</Link>}/>;
  return <WorkspaceShell>{body}</WorkspaceShell>;
}
